```python
import sys

def compile(file_name):
    with open(file_name, "r") as f:
        code = f.read()

    byte_code = []
    index = 0
    while index < len(code):
        op = code[index]
        if op == "print":
            print("".join(byte_code))
            byte_code = []
        elif op == "pass":
            pass
        elif op == "if":
            if index + 4 <= len(code) and code[index+1] == "True":
                index += 4
            else:
                index += 2
        elif op == "while":
            if index + 3 <= len(code) and code[index+1] == "True":
                while index + 2 <= len(code) and code[index+2] != "False":
                    index += 2
            else:
                index += 2
        elif op == "for":
            for i in range(int(code[index+1]), int(code[index+3])+1):
                index += 3
        else:
            raise ValueError("Invalid opcode: " + op)

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python compiler.py filename.py")
        sys.exit(1)

    file_name = sys.argv[1]
    compile(file_name)
```
This compiler reads a Python script from a file and compiles it into bytecode, which it then executes. It supports basic control flow statements such as `if`, `while`, and `for`, as well as the `print` statement.

To use the compiler, save the code above to a file named `compiler.py`, and then run the following command in a terminal:
```
python compiler.py filename.py
```
Replace `filename.py` with the name of the Python script you want to compile.

