        for col in range(len(labyrinth[0])):
            # Calculate the coordinates of the top-left corner of the cell
            x0, y0 = col * cell_width, row * cell_height
            x1, y1 = x0 + cell_width, y0 + cell_height

            # Draw the floor of the cell
            if not labyrinth[row][col]:
                canvas.create_rectangle(x0, y0, x1, y1, fill=floor_color, outline="")

            # Draw the walls of the cell
            if labyrinth[row][col]:
                if row == 0:
                    canvas.create_line(x0, y0, x1, y0, fill=wall_color, width=2)
