    return random.choice(operations)

def generate_question(max_num, operations):
    num1 = random_number(max_num)
    num2 = random_number(max_num)
    operation = arithmetic_operation(operations)

    # Limit the maximum number for division problems
    if operation == '/':
        max_num2 = max_num // 2
        num2 = random_number(max_num2)

    if operation == '+':
        answer = num1 + num2
    elif operation == '-':
        answer = num1 - num2
    elif operation == '*':
        answer = num1 * num2
    elif operation == '/':
        if num2 == 0:
            return None
        answer = num1 / num2

    return f"{num1} {operation} {num2}", answer

def main():
    max_num = 20
    operations = ['+', '-', '*', '/']

    while True:
        question, answer = generate_question(max_num, operations)
        if question:
            print(question)
            user_answer = float(input("Your answer: "))
            if user_answer == answer:
                print("Correct!")
            else:
                print("Wrong. The correct answer is:", answer)
        else:
            print("Invalid question generated. Please try again.")

if __name__ == "__main__":
    main()
```
Now, the script will limit the maximum number for division problems, making the generated questions more manageable for humans.

The most efficient way to compute the nth Fibonacci number in Python for large inputs is to use matrix exponentiation. This approach has a time complexity of O(log n) and is much faster than the traditional recursive or iterative solutions.

Here's an example implementation:

```python
def fib(n):
    if n <= 1:
        return n
    matrix = [[1, 1], [1, 0]]
    result = matrix_pow(matrix, n-1)
    return result[0][0]

def matrix_mul(a, b):
    zip_b = list(zip(*b))
    return [[sum(ele_a*ele_b for ele_a, ele_b in zip(row_a, col_b)) for col_b in zip_b] for row_a in a]

def matrix_pow(mat, n):
    if n == 1:
        return mat
    elif n % 2 == 0:
        sqrt_mat = matrix_pow(mat, n//2)
        return matrix_mul(sqrt_mat, sqrt_mat)
    else:
        sqrt_mat = matrix_pow(mat, (n-1)//2)
        return matrix_mul(matrix_mul(sqrt_mat, sqrt_mat), mat)
```

The `fib()` function takes an integer `n` as input and returns the nth Fibonacci number. The `matrix_mul()` function performs matrix multiplication, and the `matrix_pow()` function implements matrix exponentiation.

To compute the nth Fibonacci number, we first initialize a 2x2 matrix `matrix` with values `[1, 1]` and `[1, 0]`. We then call `matrix_pow(matrix, n-1)` to raise the matrix to the power of `n-1`, and return the value at position `[0][0]`.

