    // Set the data and header for the new HDU
    double *data = (double*)malloc(10*10*sizeof(double));
    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 10; j++) {
            data[i*10+j] = i+j;
        }
    }
    new_hdu->data = data;
    new_hdu->header = CFITS_HDU_HAVE_IMAGE;

    // Write the new HDU to the FITS file
    cfitsio_write_hdu(fptr, new_hdu, &errmsg);

    // Close the FITS file
    cfitsio_fits_close(fptr, &errmsg);
    free(data);
