class Game:
    def __init__(self, board):
        self.board = board
        self.running = False
        self.stepMode = False
        self.previousStates = []
        self.generation = 0

    def updateState(self):
        newBoardState = [[False] * self.board.cols for row in range(self.board.rows)]
        for row in range(self.board.rows):
            for col in range(self.board.cols):
                liveNeighbors = self.countLiveNeighbors(row, col)
                cellAlive = self.board.state[row][col]
                if cellAlive and 2 <= liveNeighbors <= 3:
                    newBoardState[row][col] = True
                elif not cellAlive and liveNeighbors == 3:
                    newBoardState[row][col] = True
        self.previousStates.append(self.board.state)
        if len(self.previousStates) > 5:
            self.previousStates.pop(0)
        self.board.state = newBoardState
        self.generation += 1

    def countLiveNeighbors(self, row, col):
        count = 0
        for r in range(-1, 2):
            for c in range(-1, 2):
                if r != 0 or c != 0:
                    newRow = (row + r) % self.board.rows if self.board.wrapEdges else row + r
                    newCol = (col + c) % self.board.cols if self.board.wrapEdges else col + c
                    if 0 <= newRow < self.board.rows and 0 <= newCol < self.board.cols:
                        count += self.board.state[newRow][newCol]
        return count

    def reset(self):
        self.running = False
        self.board.initializeState()
        self.generation = 0

    def isSteadyState(self):
        for prevState in self.previousStates:
            if prevState == self.board.state:
                return True
        return False

    def toggleStepMode(self):
        self.stepMode = not self.stepMode
