```c++
#include <atomic>
#include <thread>
#include <random>

std::atomic<int> sum(0);

void thread_function() {
    for (int i = 0; i < 10; i++) {
        int random_num = std::rand() % 256;
        sum.fetch_add(random_num);
    }
}

int main() {
    for (int i = 0; i < 10; i++) {
        std::thread t(&thread_function);
        t.join();
    }
    std::cout << "The sum is: " << sum << std::endl;
    return 0;
}

```

