Here's an example of how you can implement the `knn.fit` method in Python without using scikit-learn:
```python
import numpy as np

class KNN:
    def __init__(self, n_neighbors=5):
        self.n_neighbors = n_neighbors

    def fit(self, X, y):
        self.X_train = X
        self.y_train = y
        self.X_test = np.empty((X.shape[0], self.n_neighbors))
        self.y_test = np.empty((X.shape[0], 1))
        for i in range(X.shape[0]):
            for j in range(self.n_neighbors):
                if i == j:
                    continue
                distances = np.linalg.norm(X[i] - X[j], axis=1)
                self.X_test[i, j] = distances
                self.y_test[i, j] = np.round(self.predict(X[i], y)[:, 1])

        self.X_train = np.hstack((self.X_train, self.X_test))
        self.y_train = np.hstack((self.y_train, self.y_test))

    def predict(self, X, y):
        n_neighbors = self.n_neighbors
        distances = np.linalg.norm(X, axis=1)
        probabilities = np.zeros(n_neighbors)
        for i in range(n_neighbors):
            for j in range(X.shape[0]):
                distances[i, j] = np.linalg.norm(X[j] - self.X_train[i], axis=1)
                probabilities[i] += distances[i, j] ** 2
        return probabilities / np.sum(probabilities)
```
