```rust
use std::str::CharIndices;

fn tokenize_twitter_text(text: &str) -> Vec<&str> {
    let mut tokens: Vec<&str> = text.split('/').collect();

    let mut char_indices = CharIndices::from_chars(text);
    let mut token_start = 0;
    loop {
        let token_end = match char_indices.get(token_start..).unwrap() {
            "\n" => token_start + 1,
            c if c.is_whitespace() || c.is_ascii_punctuation() => token_start + 1,
            _ => token_start,
        };
        if token_end == token_start {
            break;
        }
        let token = &text[token_start..token_end];
        tokens.push(token);
        token_start = token_end;
    }

    tokens
}
```
