class BidirectionalGraph:
    def __init__(self):
        self.nodes = {}
        self.edges = {}

    def add_node(self, node):
        self.nodes[node] = []

    def add_edge(self, node1, node2):
        if node1 not in self.nodes:
            self.nodes[node1] = []
        self.nodes[node1].append(node2)

        if node2 not in self.nodes:
            self.nodes[node2] = []
        self.nodes[node2].append(node1)

    def neighbors(self, node):
        if node in self.nodes:
            return [n for n in self.nodes[node] if n != node]
        else:
            return []

    def remove_node(self, node):
        if node not in self.nodes:
            return
        del self.nodes[node]
        for neighbors in self.nodes.values():
            if node in neighbors:
                neighbors.remove(node)

    def __str__(self):
        str_nodes = []
        for node in self.nodes:
            str_nodes.append(str(node) + " : " + str(self.nodes[node]))
        str_edges = []
        for node1, node2 in self.edges.items():
            str_edges.append(str(node1) + " -> " + str(node2))
        return "Digraph G {\n" + "\n".join(str_nodes) + "\n" + "\n".join(str_edges) + "}"
