    public class SelfBot : DiscordClient
    {
        private readonly CommandDefinition selfCommand = new CommandDefinition("self", new[] { CommandCategory.Utility }, "Send a message with your bot token", async (interaction, command) =>
        {
            interaction.ReplyAsync("Your bot token is: " + Configuration.BotToken);
        });

        public SelfBot(string botToken)
        {
            Configuration.BotToken = botToken;
            var builder = new ConfigurationBuilder();
            builder.AddCommand(selfCommand);
            Configuration = builder.Build();
        }

        protected override void OnMessageReceived(Message message)
        {
            if (message.Author.Id == Configuration.BotToken)
            {
                return;
            }

            var lastMessage = GetLastMessage(message.Channel);

            if (lastMessage != null &&
                lastMessage.Author.Id != message.Author.Id &&
                lastMessage.Content.Equals(message.Content))
            {
                message.DeleteAsync();
                message.Channel.SendMessage("Same message received!");
            }

            base.OnMessageReceived(message);
        }

        private Message GetLastMessage(TextChannel channel)
        {
            var messages = channel.Messages.OrderBy(m => m.CreatedAt).ToList();
            return messages.Last();
        }
    }
}
