```python
def my_sort(A):
    n = len(A)
    # Traverse through all the elements of the array
    for i in range(n):
        # Last i elements are already sorted
        for j in range(0, n-i-1):
            # Swap if the element found is greater than the next element
            if A[j] > A[j+1]:
                A[j], A[j+1] = A[j+1], A[j]
    # Use pivoting to sort the last i elements
    pivot_index = n // 2
    pivot = A[pivot_index]
    for j in range(pivot_index+1, n):
        if A[j] < pivot:
            A[j], A[j-1] = A[j-1], A[j]
    # Reverse the order of the last i elements
    for i in range(n-1, -1, -1):
        A[i], A[i+1] = A[i+1], A[i]
    return A
```

