#include <iostream>
using namespace std;

vector<int> fibonacci(int n) {
    vector<int> result;
    int a = 0, b = 1;
    for (int i = 0; i < n; ++i) {
        result.push_back(a);
        a = b;
        b = a + b;
    }
    return result;
}

