import SpriteKit

class GameView: SKView {
    var ballPosition: CGPoint = CGPoint(x: UIScreen.main.bounds.width / 2, y: UIScreen.main.bounds.height - 80)
    var ballDirection: CGVector = CGVector(dx: 2, dy: -2)
    var paddlePosition: CGPoint = CGPoint(x: UIScreen.main.bounds.width / 2, y: UIScreen.main.bounds.height - 40)
    var paddleDirection: CGVector = CGVector(dx: 2, dy: 0)

    override func update(_ currentTime: TimeInterval) {
        // Update the ball position
        ballPosition = CGPoint(x: ballPosition.x + ballDirection.dx, y: ballPosition.y + ballDirection.dy)

        // Check for wall collisions
        if ballPosition.x <= 10 || ballPosition.x >= UIScreen.main.bounds.width - 10 {
            ballDirection.dx = -ballDirection.dx
        }

        if ballPosition.y <= 10 {
            ballDirection.dy = -ballDirection.dy
        }

        // Check for paddle collision
        if ballPosition.y >= paddlePosition.y - 10 && ballPosition.x >= paddlePosition.x - 50 && ballPosition.x <= paddlePosition.x + 50 {
            ballDirection.dy = -ballDirection.dy
        }

        // Update the paddle position
        paddlePosition = CGPoint(x: paddlePosition.x + paddleDirection.dx, y: paddlePosition.y + paddleDirection.dy)

        // Check for wall collisions
        if paddlePosition.x <= 10 {
            paddleDirection.dx = -paddleDirection.dx
        }

        if paddlePosition.y <= 10 {
            paddleDirection.dy = -paddleDirection.dy
        }

