        self.ui = ui
        self.direction = "Right"
        self.body = [(10, 10), (10, 20), (10, 30)]

    def changeDirection(self, newDirection):
        opposite = {"Up": "Down", "Down": "Up", "Left": "Right", "Right": "Left"}
        if newDirection != opposite[self.direction]:
            self.direction = newDirection

