        if self.direction == "Up":
            y -= 10
        elif self.direction == "Down":
            y += 10
        elif self.direction == "Left":
            x -= 10
        elif self.direction == "Right":
            x += 10
        newHead = (x, y)
        self.body.insert(0, newHead)
        self.body.pop()

    def grow(self):
        tail = self.body[-1]
        self.body.append(tail)

    def checkCollision(self):
        head = self.body[0]
        if head in self.body[1:]:
            return True
        x, y = head
        if x < 0 or y < 0 or x >= self.ui.gridWidth or y >= self.ui.gridHeight:
            return True
        return False

    def checkFood(self, foodPosition):
        if self.body[0] == foodPosition:
            return True
        return False
